package com.example.primenestprop.common;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Component;
import org.springframework.web.multipart.MultipartFile;

/**
 * Private agency documents (inspection photos, generated reports): S3-compatible storage when
 * configured, local disk otherwise. Keys are generated by the server, and local paths are checked
 * to stay inside the root.
 */
@Component
public class DocumentStore {
    private final ObjectStorageService objectStorage;
    private final Path root;

    public DocumentStore(ObjectStorageService objectStorage,
                         @Value("${app.storage.agency-documents:storage/agency-documents}") String root) {
        this.objectStorage = objectStorage;
        this.root = Path.of(root).toAbsolutePath().normalize();
    }

    /** Where to fetch a stored object: a local file, or a short-lived URL. */
    public record Located(Path localPath, String redirectUrl) {
    }

    public void put(String key, MultipartFile file) {
        if (objectStorage.isConfigured()) {
            objectStorage.put(key, file);
            return;
        }
        try (InputStream in = file.getInputStream()) {
            write(key, in);
        } catch (IOException e) {
            throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR, "Could not store the file");
        }
    }

    public void putBytes(String key, byte[] bytes, String contentType) {
        if (objectStorage.isConfigured()) {
            objectStorage.putBytes(key, bytes, contentType);
            return;
        }
        try (InputStream in = new java.io.ByteArrayInputStream(bytes)) {
            write(key, in);
        } catch (IOException e) {
            throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR, "Could not store the file");
        }
    }

    public Located locate(String key) {
        if (objectStorage.isConfigured()) {
            return new Located(null, objectStorage.presignedUrl(key));
        }
        return new Located(resolve(key), null);
    }

    public void delete(String key) {
        if (objectStorage.isConfigured()) {
            objectStorage.delete(key);
            return;
        }
        try {
            Files.deleteIfExists(resolve(key));
        } catch (IOException ignored) {
            // best effort
        }
    }

    private void write(String key, InputStream in) throws IOException {
        Path target = resolve(key);
        Files.createDirectories(target.getParent());
        Files.copy(in, target, StandardCopyOption.REPLACE_EXISTING);
    }

    private Path resolve(String key) {
        Path target = root.resolve(key).normalize();
        if (!target.startsWith(root)) {
            throw new ApiException(HttpStatus.BAD_REQUEST, "Invalid storage key");
        }
        return target;
    }
}
